from ta_moler.device.nokia_unix_remote3 import NokiaUnixRemote3
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class Positioner1DKrk3(NokiaUnixRemote3):
    r"""
    Positioner Krk device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      POSITIONER_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.positioner_1d_krk.Positioner1DKrk
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
                set_timeout: null
          PROXY_PC:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: tty-server15002900.nsn-rdnet.net
                login: emssim
                password: password15002900
                expected_prompt: emssim@tty-server\d+.*$
                set_timeout: null
          UNIX_REMOTE:
            POSITIONER:
              execute_command: sudo
              command_params:
                sudo_params: python3 ~/positioner_software/cli.py
                password: password15002900
            PROXY_PC:
              command_params:
                expected_prompt: "proxy_pc#"

    -without PROXY_PC:
      POSITIONER:
        DEVICE_CLASS: ta_moler.device.positioner_1d_krk.Positioner1DKrk
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: tty-server15002900.nsn-rdnet.net
                login: emssim
                password: password15002900
                expected_prompt: emssim@tty-server\d+.*$
                set_timeout: null
          UNIX_REMOTE:
            POSITIONER:
              execute_command: sudo
              command_params:
                sudo_params: python3 ~/positioner_software/cli.py
                password: password15002900
    """

    positioner = "POSITIONER"
    unix_remote_positioner = "UNIX_REMOTE_POSITIONER"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create PositionerKrk device communicating over io_connection.

        :param sm_params: dict with parameters of state machine for device
        :param name: name of device
        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: type of connection - tcp, udp, ssh, telnet, ...
        :param variant: connection implementation variant, ex. 'threaded', 'twisted', 'asyncio', ...
                        (if not given then default one is taken)
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: name of initial state. State machine tries to enter this state just after creation.
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        initial_state = initial_state if initial_state is not None else Positioner1DKrk3.positioner
        super(Positioner1DKrk3, self).__init__(name=name, io_connection=io_connection,
                                               io_type=io_type, variant=variant,
                                               io_constructor_kwargs=io_constructor_kwargs,
                                               sm_params=sm_params, initial_state=initial_state,
                                               lazy_cmds_events=lazy_cmds_events)

    def _get_positioner_krk_default_sm_configuration(self):
        config = {
            Positioner1DKrk3.connection_hops: {
                Positioner1DKrk3.unix_remote: {  # from
                    Positioner1DKrk3.unix_remote_positioner: {  # to
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "~/positioner_software/",
                            "expected_prompt": r'(emssim|user-lab0)@([\w-]+\d*):\s*~/positioner_software.*\$',
                        },
                        "required_command_params": [
                        ]
                    }
                },
                Positioner1DKrk3.unix_remote_positioner: {  # from
                    Positioner1DKrk3.positioner: {  # to
                        "execute_command": "sudo",  # using command
                        "command_params": {  # with parameters
                            "sudo_params": "python3 cli.py",
                            "password": ["emssim4Krakow$", "NokiaBts2003"],
                            "expected_prompt": r"positioner.*>"
                        },
                        "required_command_params": [
                        ]
                    },
                    Positioner1DKrk3.unix_remote: {  # to
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "~",
                            "expected_prompt": r'(emssim|user-lab0)@([\w-]+\d*):(?!(~/positioner_software))',
                        }
                    },
                },
                Positioner1DKrk3.positioner: {  # from
                    Positioner1DKrk3.unix_remote_positioner: {  # to
                        "execute_command": "exit",  # using commands
                        "command_params": {  # with parameters
                            "expected_prompt": r'(emssim|user-lab0)@([\w-]+\d*):\s*~/positioner_software\s*\$',
                        },
                    },
                },
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        return self._get_positioner_krk_default_sm_configuration()

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_without_proxy_pc(self):
        """
        Return State Machine default configuration without proxy_pc state.

        :return: default sm configuration without proxy_pc state.
        """
        return self._get_positioner_krk_default_sm_configuration()

    def _prepare_transitions(self):
        super(Positioner1DKrk3, self)._prepare_transitions()
        transitions = {
            Positioner1DKrk3.positioner: {
                Positioner1DKrk3.unix_remote_positioner: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Positioner1DKrk3.unix_remote: {
                Positioner1DKrk3.unix_remote_positioner: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Positioner1DKrk3.unix_remote_positioner: {
                Positioner1DKrk3.unix_remote: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Positioner1DKrk3.positioner: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            }
        }
        self._add_transitions(transitions=transitions)

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {
            Positioner1DKrk3.not_connected: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_local,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_local
            },
            Positioner1DKrk3.unix_local: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.proxy_pc,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.proxy_pc,
            },
            Positioner1DKrk3.unix_local_root: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_local,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_local,
            },
            Positioner1DKrk3.proxy_pc: {
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote,
            },
            Positioner1DKrk3.unix_remote: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote_positioner,
            },
            Positioner1DKrk3.positioner: {
                Positioner1DKrk3.unix_local: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_local_root: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.not_connected: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_remote_root: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_remote: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.proxy_pc: Positioner1DKrk3.unix_remote_positioner,
            },
            Positioner1DKrk3.unix_remote_positioner: {
                Positioner1DKrk3.unix_local: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_local_root: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.not_connected: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_remote_root: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.proxy_pc: Positioner1DKrk3.unix_remote,
            },
            Positioner1DKrk3.unix_remote_root: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.proxy_pc: Positioner1DKrk3.unix_remote
            }
        }

        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        state_hops = {
            Positioner1DKrk3.not_connected: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_local,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_local
            },
            Positioner1DKrk3.unix_local: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_remote,
            },
            Positioner1DKrk3.unix_local_root: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_local,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_local,
            },
            Positioner1DKrk3.unix_remote: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote_positioner,
            },
            Positioner1DKrk3.positioner: {
                Positioner1DKrk3.unix_local: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_local_root: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.not_connected: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_remote_root: Positioner1DKrk3.unix_remote_positioner,
                Positioner1DKrk3.unix_remote: Positioner1DKrk3.unix_remote_positioner,
            },
            Positioner1DKrk3.unix_remote_positioner: {
                Positioner1DKrk3.unix_local: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_local_root: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.not_connected: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_remote_root: Positioner1DKrk3.unix_remote,
            },
            Positioner1DKrk3.unix_remote_root: {
                Positioner1DKrk3.positioner: Positioner1DKrk3.unix_remote,
                Positioner1DKrk3.unix_remote_positioner: Positioner1DKrk3.unix_remote,
            }
        }
        return state_hops

    def _prepare_positioner_krk_state_prompts(self):
        state_prompts = {
            Positioner1DKrk3.positioner:
                self._configurations[Positioner1DKrk3.connection_hops][Positioner1DKrk3.unix_remote_positioner][
                    Positioner1DKrk3.positioner]["command_params"]["expected_prompt"],
            Positioner1DKrk3.unix_remote_positioner:
                self._configurations[Positioner1DKrk3.connection_hops][Positioner1DKrk3.positioner][
                    Positioner1DKrk3.unix_remote_positioner]["command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        return self._prepare_positioner_krk_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        return self._prepare_positioner_krk_state_prompts()

    def _get_packages_for_state(self, state, observer):
        available = super(Positioner1DKrk3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == Positioner1DKrk3.positioner:
                available = {
                    Positioner1DKrk3.cmds: ['ta_moler.cmd.positioner_1d_krk'],
                    Positioner1DKrk3.events: ['moler.events.shared', 'moler.events.unix'],
                }
            elif state == Positioner1DKrk3.unix_remote_positioner:
                available = {
                    Positioner1DKrk3.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix'],
                    Positioner1DKrk3.events: ['moler.events.shared', 'moler.events.unix']
                }
            if available:
                return available[observer]

        return available

    def goto_state(self, state, timeout=-1, rerun=0, send_enter_after_changed_state=False,
                   log_stacktrace_on_fail=True, keep_state=True, timeout_multiply=1.0,
                   sleep_after_changed_state=0.5):
        """
        Go to specific state.

        :param state: Name to state to change on the device.
        :param timeout: Timeout for changing state, if negative then timeout from commands are taken.
        :param rerun: How many times rerun the procedure before it fails.
        :param send_enter_after_changed_state: If True then enter is sent after state is changed. False nothing is sent.
        :param log_stacktrace_on_fail: Set True to have stacktrace in logs when failed, otherwise False.
        :param keep_state: if True and state is changed without goto_state then device tries to change state to state
        defined by goto_state.
        :param timeout_multiply: how many times multiply passed timeout to get final timeout.
        :return: None
        :raise: DeviceChangeStateFailure if cannot change the state of device.
        """
        return super(Positioner1DKrk3, self).goto_state(state=state, timeout=timeout, rerun=rerun,
                                                        send_enter_after_changed_state=send_enter_after_changed_state,
                                                        log_stacktrace_on_fail=log_stacktrace_on_fail,
                                                        keep_state=keep_state, timeout_multiply=timeout_multiply,
                                                        sleep_after_changed_state=sleep_after_changed_state)
